import{d as u,C as t,o as c,c as g,j as a,a as s,E as i,a3 as m}from"./chunks/framework.Q4yG9rk_.js";const _=JSON.parse('{"title":"道德经第七十五章","description":"从食税、有为、求生过厚读在上者与民之困境的关系，辨无以生为与贵生。","frontmatter":{"title":"道德经第七十五章","description":"从食税、有为、求生过厚读在上者与民之困境的关系，辨无以生为与贵生。","category":"guide","aliases":["道德经第七十五章","老子第七十五章","dao de jing chapter 75"],"source":["王弼《道德真经注》卷四"]},"headers":[],"relativePath":"daoism/dao-de-jing/chapter-75.md","filePath":"daoism/dao-de-jing/chapter-75.md","lastUpdated":1794189804000}'),p={name:"daoism/dao-de-jing/chapter-75.md"},y=u({...p,setup(b){const r=[{id:"hunger-and-excessive-tax-consumption",label:"民之饥，以其上食税之多",showLabel:!0,sentences:[["民之饥，以其",{text:"上",glossary:"shang"},{text:"食税",glossary:"shishui"},"之多，是以饥。"]],note:["【白话】百姓之所以饥饿，是因为在上者耗用的赋税太多，所以陷于饥饿。经文将民的匮乏，与居上者的取用直接相连。","【读法】食税不只是有赋税收入，而是此句所批评的食税之多。问题落在取用过多怎样损害民的生计，不只把饥饿看成个人能力或品德问题。"]},{id:"difficulty-and-imposed-interference",label:"民之难治，以其上之有为",showLabel:!0,sentences:[["民之难治，以其",{text:"上",glossary:"shang"},"之",{text:"有为",glossary:"youwei"},"，是以难治。"]],note:["【白话】百姓之所以难以治理，是因为在上者强作干预、不断施为，所以造成难治。经文继续把所见的困难追问到居上者的作为。","【读法】有为在这里连民难治的反效读，不等于所有行动都有错。可与第五十七章我无为而民自化、第六十五章智术相激的说明参读。","【读法】今天相参时，可以追问要求、规则和激励是否正在制造抵抗；这是现代检视，不把古文直接说成取消一切治理责任。"]},{id:"disregarding-death-and-excessive-self-preservation",label:"民之轻死，以其上求生之厚",showLabel:!0,sentences:[["民之",{text:"轻死",glossary:"qingsi"},"，以其",{text:"上",glossary:"shang"},"求生之",{text:"厚",glossary:"hou"},"，是以",{text:"轻死",glossary:"qingsi"},"。"]],note:["【白话】依本站现文，百姓之所以不再把死亡看得那么重，是因为在上者过分追求自己的厚养与保全，损害了民的生活，所以使民轻死。","【王弼注择要】篇末总注说「言民之所以僻、治之所以乱，皆由上，不由其下也」，又说「民从上也」，将全章的责任指向在上者。","【读法】本站此句有其上，所据录文作以其求生之厚，无上字；前面的白话明示依本站现文，王注总论另列，不将它冒作上字也见于录文的证明。","【读法】轻死连第七十四章民不畏死，可理解为民生受损时不再受死亡威吓。经文在追究这种处境的成因，不是在劝人轻弃生命。"]},{id:"not-making-thick-nurture-the-goal",label:"夫唯无以生为者",showLabel:!0,sentences:[["夫唯",{text:"无以生为",glossary:"wuyishengwei"},"者，是",{text:"贤",glossary:"xian"},"于",{text:"贵生",glossary:"guisheng"},"。"]],note:["【白话】不把厚养自身当作一味经营目标的人，比过分看重自身、专求保全生命的人更好。末句承前面的求生之厚，比较两种对待自身的取向。","【读法】贤于是胜过、较好，贵生在这里连过厚的求生读。可以与第五十章生生之厚相参，不用刻意加重求生之欲来反而损害生命。","【读法】所据本句后是针对全章的集中总注，未另给无以生为逐词训释。本页依上下文说明，不把现代照料、身心健康的建议说成王注原话。"]}],o=[{id:"shang",term:"上",sense:3},{id:"shishui",term:"食税",sense:1},{id:"youwei",term:"有为",sense:1},{id:"qingsi",term:"轻死",sense:1},{id:"hou",term:"厚",sense:1},{id:"wuyishengwei",term:"无以生为",sense:1},{id:"xian",term:"贤",sense:1},{id:"guisheng",term:"贵生",sense:1}];return(x,e)=>{const n=t("DaoReadingPrelude"),l=t("DaoTextReading"),d=t("DaoLineGuide"),h=t("DaoKeywordCards");return c(),g("div",null,[e[0]||(e[0]=a("h1",{id:"道德经第七十五章",tabindex:"-1"},[s("道德经第七十五章 "),a("a",{class:"header-anchor",href:"#道德经第七十五章","aria-label":'Permalink to "道德经第七十五章"'},"​")],-1)),i(n,{title:"民饥、民难治，为什么都回问在上者",summary:"三句民之分别谈饥、难治与轻死，归因却反复指向在上者：食税过多、强作干预、求生过厚。王弼在篇末明确说皆由上、不由其下。结尾再比较不专事厚养自身与过分贵生，不能只读成责怪百姓不珍惜生命。",points:[{label:"先读",text:"把三句民之连读，留意每次以其之后怎样指向居上者。"},{label:"再辨",text:"本站第三句有其上，所据录文无上字；两者保留，王注总论仍明确归因于上。"},{label:"后看",text:"无以生为与贵生比较的是专事厚养的取向，不是要求放弃适当养护生命。"}],hint:"食税读 shí shuì，有为读 yǒu wéi，厚读 hòu，贤于取胜过、较好之义。上在本章指在上的治理者。"}),e[1]||(e[1]=a("h2",{id:"【原典层】原文与段释义",tabindex:"-1"},[s("【原典层】原文与段释义 "),a("a",{class:"header-anchor",href:"#【原典层】原文与段释义","aria-label":'Permalink to "【原典层】原文与段释义"'},"​")],-1)),i(l,{sections:r,glossary:o}),e[2]||(e[2]=a("h2",{id:"【原典层】核心句引读",tabindex:"-1"},[s("【原典层】核心句引读 "),a("a",{class:"header-anchor",href:"#【原典层】核心句引读","aria-label":'Permalink to "【原典层】核心句引读"'},"​")],-1)),i(d,{lines:[{text:"民之饥，以其上食税之多，是以饥。",tone:"从民困回问取用",guide:"饥不是孤立的个人处境，与在上者食税过多相连。"},{text:"民之难治，以其上之有为，是以难治。",tone:"困难也可能由治理制造",guide:"不只问民为何不服从，还要看居上者如何施为。"},{text:"夫唯无以生为者，是贤于贵生。",tone:"回收求生过厚之戒",guide:"比较的是专求厚养的取向，不把适当照护生命一并否定。"}]}),e[3]||(e[3]=a("h2",{id:"【原典层】字词释义",tabindex:"-1"},[s("【原典层】字词释义 "),a("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),i(h,{items:o}),e[4]||(e[4]=m('<h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-这章主要在责怪百姓吗" tabindex="-1">象：这章主要在责怪百姓吗？ <a class="header-anchor" href="#象-这章主要在责怪百姓吗" aria-label="Permalink to &quot;象：这章主要在责怪百姓吗？&quot;">​</a></h3><p>三句都以民的困境起笔，却把原因转到在上者。王注更明确说皆由上、不由其下。若只读出百姓难治或轻死，而不看食税、有为与求生过厚，就错过了本章反复追问的方向。</p><h3 id="理-第三句有无上字-为什么要注明" tabindex="-1">理：第三句有无上字，为什么要注明？ <a class="header-anchor" href="#理-第三句有无上字-为什么要注明" aria-label="Permalink to &quot;理：第三句有无上字，为什么要注明？&quot;">​</a></h3><p>本站现文直接写在上者求生过厚，所据录文只作其求生之厚，字面主语的提示不同。王注总论虽归因于上，仍不能拿解释去补造录文中没有的字，故分别交代。</p><h3 id="用-无以生为是否意味着不必珍惜自己" tabindex="-1">用：无以生为是否意味着不必珍惜自己？ <a class="header-anchor" href="#用-无以生为是否意味着不必珍惜自己" aria-label="Permalink to &quot;用：无以生为是否意味着不必珍惜自己？&quot;">​</a></h3><p>末句连前文的厚来读，所反省的是一味厚养与强求保全。适当照料自身与减少过度索取可以并存；现代相参时，还要看自己的生活安排是否把代价转给他人。</p><h2 id="【解读层】现代解读与启发" tabindex="-1">【解读层】现代解读与启发 <a class="header-anchor" href="#【解读层】现代解读与启发" aria-label="Permalink to &quot;【解读层】现代解读与启发&quot;">​</a></h2><p><strong>从自己施加的条件开始复盘。</strong> 面对参与者疲惫、难以配合或退出，先检查资源分配、反复要求和隐性成本。居上者能调整的条件，常比责怪别人态度更值得先看。</p><p><strong>让自我照料不以透支他人为代价。</strong> 照顾自己的需要时，也说明资源从何而来、谁在承担后果。求生之厚的现代提问，可以从这种分配关系开始，而不只是个人节欲。</p><h2 id="【个人记录】我的笔记" tabindex="-1">【个人记录】我的笔记 <a class="header-anchor" href="#【个人记录】我的笔记" aria-label="Permalink to &quot;【个人记录】我的笔记&quot;">​</a></h2><p>留给自己的续读问题：当我觉得别人难以配合时，是否先检查了自己设置的条件？我为保持舒适或安全而作的安排，有哪些成本一直由别人承担？</p><h2 id="校读说明与参考来源" tabindex="-1">校读说明与参考来源 <a class="header-anchor" href="#校读说明与参考来源" aria-label="Permalink to &quot;校读说明与参考来源&quot;">​</a></h2><ul><li>正文、标点与别名沿本站保留，据卷四 009b 电子录文核对。</li><li>本站第三句作以其上求生之厚，所据录文作以其求生之厚，无上字；保留本站现文，分列录文差异与依本站作出的白话。</li><li>所据篇末总注明确说皆由上不由其下也、民从上也；本页将其作为全章总论，不伪装成无以生为或各句的逐词训释。</li><li>上另列在上者的名词义，厚复用求生过厚的义项；贤于作胜过解，无以生为与贵生依前文厚养取向对读，不引申为放弃生命照料。</li><li>古代上下治理关系与现代资源、协作启发分层；古注节引转简体并加标点，尚未逐字核对影印。</li></ul><p>参考：<a href="https://github.com/kanripo/KR5c0073/blob/b988441bd55861741c850e1dff4a2d4f895daf3d/KR5c0073_004.txt" target="_blank" rel="noreferrer">王弼《道德真经注》卷四 HFL 本电子录文，009b</a>。</p>',15))])}}});export{_ as __pageData,y as default};
